import{a as e,i as t,r as n,t as r}from"./app-W8uFEfhL.js";var i=JSON.parse(`{"path":"/","title":"MedPulse","lang":"zh-CN","frontmatter":{"title":"MedPulse","home":true,"heroImage":"/images/med-pulse.png","heroImageDark":"/images/house.png","heroText":"MedPulse · 知脉医疗","tagline":"多智能体医疗引擎：记忆、识图、检索、图谱推理、数据查询一体化调度","actions":[{"text":"即刻体验 · 问诊助手","link":"/vue2/index","type":"primary"},{"text":"技能工作台","link":"/tools/index","type":"secondary"},{"text":"文献与知识库","link":"/node/index","type":"secondary"}],"features":[{"title":"🧭 多轮对话 & 短期记忆","details":"连贯医患对话上下文，理解递进式问诊，保持会话内信息连贯，自然跟随问诊流程。"},{"title":"🧪 VLM 视觉语言模型","details":"检验报告、影像图片、化验单图文理解，支持图片上传识别、内容提取与初步解读。"},{"title":"🚀 RAG 医学知识库检索","details":"对接权威医学文献、药品说明书、诊疗规范，检索溯源，回答有据可依。"},{"title":"⚙️ 知识图谱 + 图推理","details":"疾病、症状、药物、检验指标关联推理，挖掘医学实体之间的关联关系。"},{"title":"🎯 NL2SQL 自然语言查数据","details":"用自然语言查询业务数据库，运营、病案、患者统计数据一键生成查询结果。"},{"title":"✨ 向量库长期记忆","details":"依托向量数据库持久化存储健康档案、历史问诊记录，跨会话召回长期健康信息。"}],"footer":"Built with VuePress · Keep shipping, keep learning."},"git":{"updatedTime":1792508553000,"contributors":[{"name":"zhangcheng","username":"zhangcheng","email":"2778162192@qq.com","commits":7,"url":"https://github.com/zhangcheng"}],"changelog":[{"hash":"5ae52ff768315eb1b987e0de6a9b9534c5379260","time":1792508553000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"},{"hash":"96ab7bde7d6577709db3513aec3b4da1d4a72e98","time":1778552446000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"},{"hash":"f70557aa09511808eb9de388f3b5a892b58b5ac5","time":1778551252000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"},{"hash":"a83e526e8cafc5cbecea9dcf5c5cb65a3e6351f3","time":1778483234000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"},{"hash":"c137704769dbc645c66e81b69597cb2c82b901c6","time":1753956235000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"},{"hash":"8d7eaced583f96a07d61b0adc21a409cd5c5ad52","time":1753956231000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"},{"hash":"37d0a3d3e8d6242091d3a06fc98a2a11418c72e8","time":1753945934000,"email":"2778162192@qq.com","author":"zhangcheng","message":"commit"}]},"filePathRelative":"README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h2 id="推荐使用路径" tabindex="-1"><a class="header-anchor" href="#推荐使用路径"><span>推荐使用路径</span></a></h2><blockquote><p>「会话问诊、识图解读、知识检索、图谱推理、数据查询，构建完整医疗Agent链路」</p></blockquote><div class="hint-container tip"><p class="hint-container-title">五步智能闭环</p><p>依靠短期记忆维持问诊对话，VLM解析图文报告，RAG检索权威资料，知识图谱做关联推理，向量库沉淀长期健康记录，NL2SQL支撑数据统计分析。</p></div><ol><li><strong>问诊交互阶段</strong>：开启多轮对话，依托短期记忆持续问诊，收集症状、病史基础信息。</li><li><strong>图文解析阶段</strong>：上传化验单、影像截图，由VLM视觉模型识别提取关键指标。</li><li><strong>资料溯源阶段</strong>：通过RAG检索医学知识库与文献，给出循证参考信息。</li><li><strong>关联推理阶段</strong>：调用医学知识图谱，完成症状、疾病、用药之间的关联推理校验。</li><li><strong>数据沉淀&amp;查询阶段</strong>：问诊记录存入向量数据库形成长期记忆；管理人员通过自然语言NL2SQL查询统计数据。</li></ol><h2 id="内容分区-智能体模式" tabindex="-1"><a class="header-anchor" href="#内容分区-智能体模式"><span>内容分区（智能体模式）</span></a></h2><h3 id="🧭-01-问诊舱-多轮对话与视觉解读" tabindex="-1"><a class="header-anchor" href="#🧭-01-问诊舱-多轮对话与视觉解读"><span>🧭 01｜问诊舱：多轮对话与视觉解读</span></a></h3><blockquote><p>适合：患者问诊、报告图片识别、化验单解读 <strong>立即进入：</strong> <a href="/MedPulse/vue2/" target="_blank" rel="noopener noreferrer">多轮对话Demo</a> / <a href="/MedPulse/vue3/" target="_blank" rel="noopener noreferrer">VLM图文识别</a> / <a href="/MedPulse/webpack/" target="_blank" rel="noopener noreferrer">RAG知识库检索</a></p></blockquote><h3 id="🧪-02-推理舱-图谱与skill工作台" tabindex="-1"><a class="header-anchor" href="#🧪-02-推理舱-图谱与skill工作台"><span>🧪 02｜推理舱：图谱与Skill工作台</span></a></h3><blockquote><p>适合：知识图谱调试、Agent工具编排、药品交互校验 <strong>立即进入：</strong> <a href="/MedPulse/tools/" target="_blank" rel="noopener noreferrer">Agent技能管理</a></p></blockquote><h3 id="🚀-03-存储舱-向量长期记忆航线" tabindex="-1"><a class="header-anchor" href="#🚀-03-存储舱-向量长期记忆航线"><span>🚀 03｜存储舱：向量长期记忆航线</span></a></h3><blockquote><p>适合：向量库配置、历史病历召回、记忆策略调试 <strong>立即进入：</strong> <a href="/MedPulse/node/" target="_blank" rel="noopener noreferrer">医学知识库</a></p></blockquote><h3 id="⚡-04-数据舱-nl2sql-数据查询" tabindex="-1"><a class="header-anchor" href="#⚡-04-数据舱-nl2sql-数据查询"><span>⚡ 04｜数据舱：NL2SQL 数据查询</span></a></h3><blockquote><p>适合：医院运营、病案统计、患者画像、自然语言查库 <strong>立即进入：</strong> <a href="/MedPulse/tips/" target="_blank" rel="noopener noreferrer">NL2SQL数据查询</a></p></blockquote><h2 id="本周体验挑战" tabindex="-1"><a class="header-anchor" href="#本周体验挑战"><span>本周体验挑战</span></a></h2><ul><li>Day 1-2：体验多轮问诊，测试短期记忆，验证对话上下文能否连贯理解追问</li><li>Day 3：上传检验图片，测试VLM视觉模型识别、提取报告指标能力</li><li>Day 4-5：体验RAG检索 + 知识图谱推理，验证医学知识关联与溯源效果</li><li>Day 6-7：测试长期记忆召回与NL2SQL，跨会话调取历史记录，自然语言查询统计数据</li></ul>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};